const defaultState={habits:[],logs:[],goals:[],journal:[],focus:[],reminderSent:[],settings:{theme:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light',weekStart:'monday',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,reminders:false,notificationSound:true,notificationVibration:true,quietHoursEnabled:false,quietHoursStart:'22:00',quietHoursEnd:'08:00',snoozeMinutes:10,focusDurationMinutes:25},achievements:[],syncTombstones:[],schemaVersion:1};
